      acConnector: '无（纯直流接口；交流由车辆另配 Type1）',
      protocol: 'CHAdeMO 0.9/1.x/2.0/3.0 · CAN 总线（车辆主导控制）',
      safety: 'CHAdeMO 规格 + 当地电气安全法规（适用性待确认）',
      physicalLayer: 'CAN',
      dcPins: ['DC+', 'DC-', 'PE', 'CP', 'CAN_H', 'CAN_L', 'd1', 'd2'],
      controlPins: ['CP'],
      commPins: ['CAN_H', 'CAN_L'],
      auxPins: ['d1', 'd2'],
